def solve_sequence(N_max):
    a = {1: 0}

    for n in range(2, N_max + 1):
        max_val = -1
        # Iterate i from 1 up to floor(n/2) due to symmetry
        for i in range(1, n // 2 + 1):
            # For i <= n/2, min(i, n-i) = i
            term = a[i] + a[n - i] + i
            if term > max_val:
                max_val = term
        a[n] = max_val
    return a

N_target = 2025
print(f"Calculating a_{N_target}...")
results = solve_sequence(N_target)
print(f"a_{N_target} = {results[N_target]}")

